function create_app_help(tab, guide_paths, edition)
% guide_paths：{利用者向け手順書, ビルド・利用手順書} のHTMLの場所。
% 用語・操作の説明・関数のリンクは、それぞれ対象の版（all / standard / pro）を持つ。
% 通常版では Pro 版だけの説明を表示しない。通常版のインストーラーには手順書（docs）を入れないため、手順書のボタンも出さない。
if nargin < 3, edition = app_edition(); end
is_pro = strcmp(edition, 'pro');
edition_names = struct('standard', '通常版', 'pro', 'Pro版');
% 設定画面の番号は版で違う（通常版はワードクラウドがないため1つ詰まる）。
settings_title = AnalysisController.settingsTitle(edition);
layout = uigridlayout(tab, [6, 1], 'Scrollable', 'on');
layout.RowHeight = {28, 250, 80, 250, 232, 36};
uilabel(layout, 'Text', ['Help — ' edition_names.(edition) ' / 用語と公式の関数ヘルプ'], 'FontWeight', 'bold');
terms = {
    '通常版 / Pro版', '通常版はSHAP分布・依存図まで利用できます。レジスト膜厚SHAPの三角関数／スプライン近似、極値・山間／谷間の傾き・近似残差診断、データのヒストグラム・相関マトリックス・ANOVA・Parallel Coordinates・Parallel Sets・Sankey Diagram・主成分分析・クラスタリング、汎用回帰の EBM・XGBoost・LightGBM・CatBoost とハイパーパラメータの調整・探索、拡張実験計画、ワードクラウド、GPRの加法カーネル、汎用回帰の質的変数（すべての回帰方式）、CatBoost の並べ替え列、Sobol感度解析、因果探索、階層ベイズ、コピュラ乱数生成はPro版限定。APC学習画面にはSwing Curve評価を付けません。版はビルド時に固定します。', 'pro';
    'データの傾向（グラフ）', '学習画面の「① データを開く」の「グラフで傾向を見る」タブで、読み込んだデータを学習の前に確認します。単変量の傾向は、縦軸に任意の数値の列、横軸にレコード（行の順番）または任意の列、色に任意の列を選びます。色の列は文字の列（質的変数）ならグループごとの色と凡例、数値の列なら連続した色になり、「色の扱い」で切り替えられます。グラフの種類は複数選んで一括で描けます。描いたグラフと表には番号（1. 2. …）を付けて追加し、種類を変えて描き直しても前の結果は残ります（「結果を消す」で消します。別のデータを開いたときも消えます）。学習に使うデータや列の選択は変わりません。', 'all';
    'ヒストグラム / 相関マトリックス', '（Pro版）ヒストグラムは選んだ数値の列ごとの値の分布（色の列でグループごとに重ねられます）。相関マトリックスは列どうしの Pearson の相関係数で、空欄は列の組ごとに除きます。相関は因果関係を示しません。', 'pro';
    '分散分析（ANOVA）', '（Pro版）縦軸の数値の列が、選んだ要因（1〜4列）の水準で違うかを調べます。要因が2列以上のときは主効果だけの多元配置（交互作用なし）。数値の要因は6区間に分けます。p値が小さい（目安0.05未満）ほど水準で平均が違うといえ、寄与率は全体のばらつきに占めるその要因の割合です。', 'pro';
    'Parallel Coordinates / Parallel Sets / Sankey', '（Pro版）Parallel Coordinates は数値の列を縦軸として並べ、1行を1本の線で表示します（各軸は最小〜最大で目盛り）。Parallel Sets は列の値の組み合わせを帯で表し、帯の太さが行数です。Sankey Diagram は隣り合う列の間で値がどう移るかを流れで表します。数値の列は6区間に分けます。帯の色は、「色」を選ばないとき Parallel Sets は最初の列の値、Sankey は流れの元の水準です。「色」で任意の列を選ぶと、文字の列・種類の少ない数値の列はグループごとの色で帯を分け、そのほかの数値の列は帯ごとの平均を連続した色（色の目盛りつき）で表します。', 'pro';
    '主成分分析（PCA）', '（Pro版）選んだ数値の列を標準化（平均0・標準偏差1）してから、ばらつきの大きい方向（主成分）を順に求めます。寄与率は各主成分が説明するばらつきの割合、負荷量は各列が主成分にどう効くかです。空欄を含む行は除きます。', 'pro';
    'クラスタリング / シルエット係数', '（Pro版）選んだ数値の列を標準化し、k-means 法または Ward 法（階層型）で指定した数の群に分けます。エルボー図は群の数ごとの群内平方和で、減り方が緩やかになる手前が群の数の目安です。シルエット係数は −1〜1 で、1に近いほど群がはっきり分かれています。k-means の初期値には設定の乱数seedを使います。', 'pro';
    'SHAPとMAT保存', '学習と評価（SHAPを含む）を先に行い、複数条件を比較してから選んだ1モデルをMAT保存します。SHAPは「④ 結果を比べて保存」の「選択モデルのSHAPを計算」で後から計算でき、MAT保存は不要です。「保存モデルで推定・SHAP」では、起動中に学習したモデルと読み込んだMATの両方を選べ、どのモデルでも SHAP の分布と依存図を表示します。', 'all';
    '推定・SHAP（統合）', '以前の「保存モデルで推定」と「SHAP 解析」を1つの画面にまとめました。③の「SHAPも計算する」を選ぶと（初期状態で選択）、推定と同時に SHAP（先頭最大1000行）を計算し、APC・Swing Curve・汎用回帰・面内のどのモデルでも SHAP の分布と依存図を表示します。面内推定では X・Y から求めた半径も含めた3変数の SHAP です。外すと推定だけを早く行います。', 'all';
    '散布図の色', '「実測値と予測値・残差」のタブに2つの散布図を横並びで表示し、色を入力ファイルの任意列で指定できます。数値は連続色、文字列はカテゴリ色。学習データや評価値は変わりません。', 'all';
    'SHAP依存図の色', 'SHAP依存図の上の「色の変数」で、点の色に使う説明変数を選び直せます（初期値は、その変数を除いて最も重要な説明変数）。「(単色)」も選べます。', 'all';
    '予測・SHAPの出力', '元データの説明変数・目的変数と、予測値・残差・SHAP値を1つの表に並べます。学習画面の④「予測・SHAPを1ファイルに保存」、推定・SHAP画面の「表を保存」で CSV / Excel の1ファイルに出力します。SHAPを計算していない行は空欄です。CSVはWindowsのExcelで文字化けしないよう文字コード情報（BOM）付きで保存します。', 'all';
    'Swing Curveの入力', '「② 変数を選ぶ」でモードを選びます。下地なしは膜厚の列だけ、下地ありは膜厚の列に加えて下地の説明変数を一覧から複数選びます。選んだ結果は同じ画面の「モデルへ渡す順序」の表で確認でき、膜厚（RESIST_TH）が必ず最後になります。目的変数も複数選べ、各列を別モデルで学習します。膜厚の単位はnmです。', 'all';
    '炉内補間 / バッチ', 'LP-CVDのBoatSlotと膜厚・屈折率の関係を、成膜Runごとに別々に学習します。同時処理する複数Lotは同じRunのSlotプロファイルとして扱い、異なるバッチの値は混ぜません。', 'all';
    'WaferId / 未計測', '識別子はモデルの説明変数にしません。計測列の空欄だけを未計測として除き、項目別に利用できるSlotで学習します。入力行に対応するWaferIdを予測表へ残し、入力にない生成SlotのWaferIdは空欄です。', 'all';
    'スプライン / RBF', 'スプラインはnot-a-knotの3次補間。RBFはGaussian基底＋直線トレンドで正則化します。幅と正則化は設定画面だけで編集します。幅0では学習Slot間隔の中央値の2倍を使用。両者には予測区間を付けません。', 'all';
    '3次多項式近似 / poly3', 'Run・計測項目ごとにy=a×BoatSlot³+b×BoatSlot²+c×BoatSlot+dを最小二乗法で当てはめます。スプラインと異なり、計測点を必ず通りません。学習行だけでSlot・応答を規格化し、内部Slot検証と8指標で比較します。予測区間は付けません。', 'all';
    '炉内のGPR', 'squaredexponential、matern52、rationalquadraticを比較。Fit methodは設定画面の共通値（初期exact）、線形基底・標準化を使い、各学習でカーネル量とノイズを学習します。表示する95%区間は応答の予測区間で、真の成膜値の範囲を保証するものではありません。', 'all';
    '内部Slot検証', '計測位置が5点以上の項目で、両端を固定し内部Slotを1点ずつ学習から外して予測。8指標は内部Slotの検証予測を結合して計算し、順位は同じバッチ・同じ計測項目の中で付けます。端部や外挿の精度は評価しません。', 'all';
    '炉内の外挿', '計測範囲外は初期状態で予測せずNaNと理由を表示。明示的に有効にした場合だけ計算し、表と破線で区別します。カーネル選定にも使った検証値は独立な最終評価の代わりにはなりません。', 'all';
    'GPR', ['ガウス過程回帰。入力から応答を予測するモデル。kernelを選択し、Fit methodは「' settings_title '」で全GPR共通に指定します。'], 'all';
    'swingperiodic', '（Pro版のみ）Swing Curve学習専用の周期カーネル。RESIST_THの周期成分、追加の説明変数の滑らかな影響、膜厚の線形トレンドを組み合わせます。基準周期は波長÷屈折率÷2（レジスト膜内の定在波の周期 λ/2n。既定248nm÷1.77÷2≒70.06nm）で、既定はその75〜125%で、任意の評価範囲も指定でき、固定周期ごとのGPR周辺尤度を内部で比較します。', 'pro';
    '周期の内部最適化', '（Pro版のみ）周期はKernelParametersやOptimizeHyperparametersに含めません。周期ごとに説明変数数+3個のカーネル量とノイズ等を学習し、最大の周辺対数尤度を採用します。exact以外は近似尤度。最大48候補で大域最適性は保証しません。', 'pro';
    '周辺対数尤度', 'GPRがデータを説明する程度を複雑さも含めて評価する基準。今回の周期選択では大きい値を採用します。交差検証による汎化性能ではありません。同じ入力・応答・fit_methodの候補間で比較します。', 'pro';
    'RMSE', '誤差の二乗平均の平方根。実測値と同じ単位で、小さいほど一致します。', 'all';
    '決定係数 R²', '1−Σ(実測−予測)²/Σ(実測−実測平均)²。1が完全一致、負値もあります。実測が一定なら未定義です。', 'all';
    '相関係数の2乗', 'Pearson r の2乗。予測の偏りを検出できない場合があり、決定係数 R² とは別の指標です。', 'all';
    'RMSPE / MAE', 'RMSPE は相対誤差の二乗平均平方根（%）、実測に0があれば未定義。MAE は絶対誤差の平均。', 'all';
    'KL / 相互情報量', 'KLダイバージェンスは分布の違い、相互情報量は依存の強さ。ヒストグラムと擬似度数1を使用。ビン数で値が変わります。', 'all';
    'KL / MIビン数の共通設定', ['全画面で同じ値を使います。「' settings_title '」で0（自動）または2〜1000を指定し、保存・適用します。変更は次の実行から反映し、表示中の結果は計算時の値のまま残ります。'], 'all';
    '学習時の評価', '初期状態では交差検証を使わず、学習に使ったデータでの当てはまり（RMSE・R²）で評価します。複雑なモデルほど良く見えるため、未知データの性能ではありません。③の「交差検証で評価する」を選ぶか、「保存モデルで推定・SHAP」で学習に使っていない実測列と比べて確認できます。', 'all';
    'Permutation Importance', '汎用回帰の④で表示する変数重要度。1つの説明変数の値だけを行の間で並べ替えたとき、予測の RMSE がどれだけ悪くなるか（5回の平均と標準偏差、乱数は固定）。どの回帰方式でも計算でき、学習に使ったデータで計算します。相関の強い説明変数どうしでは、片方の重要度が小さく出ることがあります。', 'all';
    'VIP', 'Variable Importance in Projection。PLS回帰のモデルで、各説明変数が PLS の成分を通じて目的変数の説明にどれだけ寄与したかを表す値。二乗の平均が1になるよう決まっており、1を超える変数が重要とされる目安です。PLS 以外の方式では表示しません。', 'all';
    '炉内のRMSEの棒グラフ', '炉内補間の④「内部Slot検証のRMSE」は、目的変数ごとに棒グラフを分けて横に並べます（単位の違う目的変数を同じ軸に載せないため）。表示するのは選択中の Run で、選択中の方式の棒を濃い色にします。', 'all';
    '条件比較', 'GPRカーネルや汎用回帰の重回帰・PLS・ランダムフォレスト・バギング木を一括検証。GPRは設定画面のFit methodを使用し、同じ分割・乱数条件を使い、未使用行の予測をまとめた8指標で比較します。検証RMSE、同値ならMAE、さらに同値なら候補順で順位を付けます。', 'standard';
    '条件比較', 'GPRカーネルや汎用回帰の重回帰・PLS・ランダムフォレスト・バギング木・EBM・XGBoost・LightGBM・CatBoostを一括検証。GPRは設定画面のFit methodを使用し、同じ分割・乱数条件を使い、未使用行の予測をまとめた8指標で比較します。検証RMSE、同値ならMAE、さらに同値なら候補順で順位を付けます。', 'pro';
    '一覧の並び順', '④のモデルの一覧は、目的変数ごとにまとめ、その中を実行の順、同じ実行の中を精度の順位（RMSEの小さい順）で並べます。損失関数を分位点にしたモデルは、同じ τ のモデルどうしで、ピンボール損失（「ピンボール損失」の列）の小さい順に別の順位を付けます（平均のモデルと RMSE では比べません）。学習に失敗したモデルは各まとまりの最後です。目的変数が複数あっても、目的変数ごとに良いモデルが上に来ます。', 'all';
    '交差検証 / 分割数', '行をランダムに2〜10群に分け、各群を学習から外して予測します。既定5分割。8指標は全行の検証予測を結合して計算し、分割別指標の単純平均ではありません。', 'standard';
    '交差検証 / 分割数', '行をランダムに2〜10群に分け、各群を学習から外して予測します。既定5分割。8指標は全行の検証予測を結合して計算し、分割別指標の単純平均ではありません。周期は各分割の学習データ内で求め直します。', 'pro';
    '比較用seed / 採用モデル', '既定seed=0で分割と候補ごとの乱数条件をそろえます。通常の単独学習の乱数設定は変更しません。候補ごとに全データの完全モデルも学習し、選択した1個を再学習せずMAT保存します。', 'all';
    '検証値の限界', 'カーネルの選定にも使った交差検証値には選定による偏りがあります。採用後は別の独立データで確認してください。ロット・時系列・同じ試料の反復などの依存を分離する機能はありません。', 'all';
    '重回帰 / PLS', '汎用回帰で選択します。重回帰は切片を含む最小二乗法。PLSは標準化した学習データをplsregressで学習します。PLS成分数は独立な説明変数数以下に指定します。損失関数を分位点にすると、重み付き最小二乗の繰り返し（IRLS）で分位点回帰を行います（PLS は成分に分位点回帰を当てはめます）。保存形式はRegression_Modelで、GPRのTrain_Modelとは別です。', 'all';
    '損失関数 / 分位点回帰', '汎用回帰の③「損失関数（GPR以外）」で選びます。二乗誤差は目的変数の平均を予測します。分位点（ピンボール損失）は目的変数の τ 分位点を予測します（τ = 0.9 なら、実測の約9割がその値以下になる線。0.5 で中央値）。規格の上限・下限に対する余裕を見たいときや、ばらつきの幅を表したいときに使います。ランダムフォレスト・バギング木は葉に入った学習データの目的変数の分布から分位点を求めます（Quantile Regression Forest）。ブースティング系は木の形を損失の勾配で選び、葉の値を残差の分位点にします。GPR はこの設定によらず平均を予測します。RMSE・R² は平均からのずれの指標なので、分位点のモデルでは参考です。④の一覧の「実測が予測以下の割合」（評価データで実測が予測以下だった行の割合）が τ に近いかで確かめます。木の方式は、葉の最小行数が小さいと学習データに合わせすぎて、学習に使っていない行でこの割合が τ からずれやすくなります。交差検証で評価し、ずれるときは葉の最小行数を大きくするか、ブースティングの学習の回数を減らしてください（一覧の名前に「分位点τ=…」が付きます）。', 'all';
    'ランダムフォレスト / バギング木', '汎用回帰で選択します。どちらも学習データから復元抽出した標本ごとに回帰木を作り、予測を平均します（木の本数は③で10〜1000、既定100）。ランダムフォレストは分岐ごとに説明変数の約1/3だけを候補にし、バギング木は全変数を候補にします。葉の最小行数は5。損失関数を分位点にすると、葉に入った学習データの目的変数の分布から分位点を求めます（Quantile Regression Forest）。復元抽出に乱数を使うため、学習のたびに結果が少し変わります。学習範囲の外では予測がほぼ一定になり、外挿には向きません。保存形式はRegression_Modelです。', 'standard';
    'ランダムフォレスト / バギング木', '汎用回帰で選択します。どちらも学習データから復元抽出した標本ごとに回帰木を作り、予測を平均します。木の本数（既定100）・葉の最小行数（既定5）・分岐で使う変数の割合（ランダムフォレストのみ。既定1/3）は③の「ハイパーパラメータ」で変えられます。復元抽出に乱数を使うため、学習のたびに結果が少し変わります。学習範囲の外では予測がほぼ一定になり、外挿には向きません。保存形式はRegression_Modelです。', 'pro';
    'EBM（GA2M）', '（Pro版）予測を「切片＋各説明変数の効果の和＋選んだ2変数の組の効果の和」で表す、説明しやすいブースティング。説明変数を1つずつ順番に小さな木で学習する周回を繰り返し、残差の説明に効く組を交互作用の組の数まで選びます。④の「EBMの形」で各変数の効果を階段状の線（質的変数は水準ごとの棒）、交互作用を色で確認できます。InterpretML の EBM と同じ考え方を MATLAB で実装したものです。', 'pro';
    'XGBoost / LightGBM / CatBoost', '（Pro版）木を1本ずつ足して損失を減らす勾配ブースティング（二乗誤差、または分位点のピンボール損失）。XGBoost 方式は段ごとに木を育て、L2正則化 λ と分岐に必要な改善 γ で木の大きさを抑えます。LightGBM 方式は改善の大きい葉から順に分け、葉の数の上限で大きさを決めます。CatBoost 方式は同じ段では同じ条件で分かれる対称木を使います。いずれも値を区間に分けたヒストグラムで分岐を探します。質的変数は、XGBoost・LightGBM 方式では水準を勾配の比の順に並べて2つの組に分け、CatBoost 方式では「並べた順で前の行だけの目的変数の平均」（Ordered Target Statistics）に置き換えます。CatBoost のハイパーパラメータ「順序付きブースティング」を1にすると、各行の勾配を、並べた順で前の行だけで学習したモデルから求めます。並べる順は③の「CatBoost の並べ替え列」（日時・処理順など。指定しなければ乱数の順）で決めます。各ライブラリそのものではなく、木の育て方と正則化の考え方を MATLAB で実装したもので、LightGBM の GOSS・EFB は含みません。', 'pro';
    '加法カーネル（GPR）', '（Pro版）汎用回帰の GPR のカーネルで additive を選ぶと、予測を「説明変数ごとの滑らかな効果の和」で表します（各列に二乗指数のカーネルと大きさを持たせて足し合わせる）。説明変数どうしの交互作用は表しませんが、各変数の効き方が読み取りやすく、変数が多くても当てはまりが崩れにくくなります。保存形式は Regression_Model です。', 'pro';
    '質的変数', '（Pro版）汎用回帰の②「質的変数として扱う列」で選んだ列（ロット・装置名など。文字の列も可）は、値ごとのグループ（水準）として扱い、すべての回帰方式で使えます。GPR は「同じ水準なら似ている度合い1、違う水準なら ρ（0〜1、列ごとに学習）」のカーネルを連続の列のカーネルに掛け合わせて（加法カーネルでは足し合わせて）学習し、加法以外のカーネルは連続の列に ARD 二乗指数を使います。重回帰・PLS は2番目以降の水準を表す0/1の列（ダミー変数）に置き換えます。ランダムフォレスト・バギング木は木が水準の組で分かれます。EBM は水準ごとの効果を学習します。XGBoost・LightGBM・CatBoost の扱いは「XGBoost / LightGBM / CatBoost」を参照してください。推定では学習時になかった水準を止めます。出力の表には水準の番号（1, 2, …。水準の名前の順）が入ります。', 'pro';
    'Sobol感度解析', '（Pro版、データを解析する）各入力を動かしたとき、出力のばらつきのうちその入力で説明できる割合を求めます。データ（Excel / CSV）から解析するときは、出力の列と入力の列を選ぶと、代替モデル（GPR または ランダムフォレスト）を学習し（交差検証の R² も表示）、入力をデータの分布（経験分布）または範囲内の一様分布で互いに独立に動かして求めます。モデルを使わずデータから直接求めた1次の指数（区間分割の相関比。行数による偏りを差し引く）も並べます。保存モデルでも求められます（範囲の初期値は学習データの最小〜最大）。1次の指数 S1 は単独の効果（Saltelli 2010）、全効果の指数 ST は交互作用を含む効果（Jansen）。ST − S1 が大きい入力はほかの入力との交互作用が強いといえます。標本はスクランブルした Sobol 列で、予測の回数は N ×（入力の数＋2）。ひげはブートストラップの95%区間です。「予測値の分布」には、平均・最頻値（密度の山の頂点）・95%区間・平均 ± nσ（n は③で指定）と、それぞれの範囲に入る割合を表示します。入力どうしの相関は考えません。', 'pro';
    'コピュラ乱数生成', '（Pro版、データを解析する）列どうしの関係を保った乱数を作ります。コピュラは、各列の分布（周辺分布）とは別に、列どうしの順位の関係だけを表すものです。データの関係をまねるときは、選んだ列を順位に直した値にコピュラ（ガウス・t・Clayton・Frank・Gumbel。後の3つは2列だけ）を当てはめ、各列の分布を経験分布・カーネル密度・正規・対数正規・ワイブル・ガンマで表します。関係を指定して作るときは、変数ごとの分布（正規・一様・対数正規・ワイブル・ガンマ・三角・指数・ベータ）とパラメータ、変数どうしの順位相関（Spearman ρ または Kendall τ）を入れます（t・Clayton・Frank・Gumbel は Kendall τ。実現できない組み合わせは止めます）。生成した乱数は表で CSV / Excel に保存でき、元（指定）と生成の順位相関、分布、散布図で比べられます。乱数seedが同じなら同じ乱数になります。経験分布ではデータの範囲の外の値は出ません。', 'pro';
    '因果探索（PC / DirectLiNGAM）', '（Pro版）選んだ数値の列どうしの因果の向きの候補を推定します。PC アルゴリズムは、偏相関の検定（Fisher の z、有意水準）で関係のない組の辺を外し、V字構造と Meek の規則で向きを決めます（向きの決まらない辺は破線）。正規分布・線形を仮定します。DirectLiNGAM は、誤差が正規分布でないことを使って因果の順序を決め、各列を順序が前の列へ回帰します（係数は標準化した値。有意でない辺は外す）。④「前もって分かっている因果」で、あり得ない向き（例：後の工程 → 前の工程）、因果はない組、因果がある向きを指定すると、それを守って推定します（PC は知識に反する向きを決めず、因果がある組は検定で外さない。DirectLiNGAM は因果の元を先に並べ、あり得ない向きを回帰に使わない）。辺の表の「事前の知識」に指定で残した辺を示します。どちらも未観測の共通原因がないことを仮定し、結果は仮説で因果の証明ではありません。', 'pro';
    '階層ベイズ / R-hat', '（Pro版）グループ（ロット・装置など）ごとに回帰係数を持たせ、それらが全体の分布から出ていると考えて推定します。データの少ないグループの係数ほど全体の平均へ引き寄せられ（縮小）、グループ単独の最小二乗より安定します。計算はギブスサンプリング（MCMC）で、目的変数・説明変数を標準化して計算し元の単位へ戻します。事前分布は弱い情報のもの（標準化した単位で N(0, 10²)、逆ウィシャート、逆ガンマ(1,1)）。R-hat は複数の鎖の結果がそろっているかの目安で、1.1 以上の量は収束していない可能性があります。区間は事後分布の 2.5〜97.5% 点です。', 'pro';
    'ハイパーパラメータ / 探索', '（Pro版）学習の前に決める設定（木の本数・深さ・学習率など）。③の「ハイパーパラメータ」で方式ごとに「値」を入れて学習するか、「探索の候補」を入れてグリッドサーチ（候補の全組み合わせ。200通りまで）またはランダムサーチ（候補の組み合わせから試行数だけ重複なしに選ぶ）で探します。各試行は③の分割数・乱数seedの交差検証の RMSE で比べ、最も良い値で全データを学習し直します。④の「探索の推移」「パラメータと精度」と「ハイパーパラメータ探索」の表で傾向を確認できます。交差検証で評価するときは、各分割の中で探索し直すため時間がかかります。分位点回帰（損失関数が分位点）では、RMSE ではなくピンボール損失の小さい値を選びます。', 'pro';
    'SHAP', 'モデルの予測に各入力がどれだけ寄与したかを示す値。因果関係を証明するものではありません。', 'all';
    'Swing Curve近似', 'Pro版でRESIST_THのSHAP値を三角関数またはスプラインで近似します。三角関数はオフセット＋直線トレンド＋一定振幅の正弦波。周期・振幅・R²・RMSEはSHAP散布点への近似結果で、GPRの評価とは別です。スプラインでは周期・一定振幅を定義しません。', 'pro';
    '極値の膜厚', '傾きを含む近似曲線の微分が0になる位置。プロット範囲内の極大・極小のみを表示します。端点を自動で極値扱いしません。', 'pro';
    '山間・谷間の傾き', '隣接する同種の極値を結ぶ傾き（SHAP値の差/膜厚の差）。三角関数の一定振幅＋直線モデルでは全区間で同じ傾きです。スプラインでは形状に応じて区間ごとに異なります。バルク効果の物理的な証明ではありません。', 'pro';
    '近似残差', 'SHAP値−Swing Curve近似値。ヒストグラムと標本平均・標準偏差の正規密度、正規Q–Q、残差対膜厚をアプリ内で表示します。GPRの実測−予測の残差とは別です。', 'pro';
    '正規性検定', 'Lilliefors検定、有意水準α=0.05。正規性を棄却できない場合も正規分布の証明ではありません。近似後の残差の依存性を補正していないためp値は参考診断です。0.001以下/0.5以上のp値は境界を明示します。', 'pro';
    '歪度 / 尖度', '偏り補正付き。歪度は左右の非対称性（正規分布0）、尖度は裾・外れ値の影響を反映する4次モーメント（正規分布3）。超過尖度は尖度−3（正規分布0）。これらの値だけで正規性を判断しません。', 'pro';
    '正規Q–Q', '横軸は標準正規分布の理論分位点、縦軸は中心化・標準化した残差の分位点。斜めの基準線からの曲がりや裾のずれを確認します。点の整列は独立性を保証しません。', 'pro';
    '列の要約', '割り当てた入力・実測・予測・残差の件数、平均、四分位数、不偏標準偏差など11項目を計算します。', 'all';
    'D最適 / I最適', 'D はモデル係数を推定する情報量、I は領域全体の平均予測分散を重視。モデルを変えると計画も変わります。', 'all';
    '計画の評価指標', '作成した計画を、選んだモデルの項で評価します。D効率（%）は係数をまとめて推定する精度で直交計画が100%、A効率（%）は係数の分散の合計、I基準は −1〜1 の領域全体の平均予測分散（誤差分散を1とした値。小さいほど良い）、G効率（%）は最も予測が悪い点の予測分散、最大VIFと項どうしの最大相関は項の重なりの強さ（VIF 10超が多重共線性の目安）、残差の自由度は実験数−項数です。「予測分散の分布（FDS）」は、領域のうち予測分散がその値以下の割合で、低く平らな線ほど領域全体で予測が安定します。', 'all';
    '直交表', '各2因子の水準組合せが均等に現れる計画。同一水準の2〜5水準に対応し、必要サイズを自動選択します。4水準は有限体GF(4)を使います。混合水準には対応しません。', 'all';
    '拡張実験計画', '既存点を先頭に固定し、指定した追加数の点を D または I 基準で探索。既存点は−1〜1に符号化して読み込みます。', 'pro';
    'ワードクラウド', '（Pro版）文章中の単語の出現数を、文字の大きさで表した図。形は楕円か長方形、配色は単色（よく出る単語だけ強調する色）・出現数で色を変える・ランダムな色から選べます。表示する単語の数と、出現数による文字の大きさの差も変えられます。「英語のよく使う語を除く」（初期状態で選択）で、I・we・you・it・be 動詞・a・the・and・of などの意味の少ない語を数えません。「ほかに除く語」にカンマで区切って入れた語も除きます（大文字・小文字は区別しません）。', 'pro';
    '交絡', '別のモデル項の効果を区別できない状態。図の対角線以外が1なら2項が同一または逆符号。複数項の関係は零空間の係数表で確認します。', 'all';
    'ランク不足', 'モデル項に独立でない組合せがあり、すべての係数を個別には推定できません。直交表でも二次モデルはランク不足になり得ます。', 'all';
    '符号化 / 外挿', '符号化は因子の下限を−1、上限を1へ変換すること。外挿は学習範囲外への予測で、精度は別途確認が必要です。', 'all'};
terms = for_edition(terms, is_pro);
glossary = uitable(layout, 'Data', terms, 'ColumnName', {'用語', '説明（選択すると下に全文）'}, 'ColumnWidth', {160, 'auto'}, 'RowName', {});
description = uitextarea(layout, 'Editable', 'off', 'Value', {'用語表の行を選択すると、ここに説明の全文を表示します。'});
glossary.CellSelectionCallback = @(~, event) showTerm(event, terms, description);
operations = {
    '学習（1〜3）：上のタブを左から進みます。① データを開く（シートとヘッダー行は画面内で変更）→ ② 目的変数と説明変数を選ぶ → ③ カーネルなどの条件を決めて実行（列の中身は実行時に自動で確認し、問題があれば②に戻って理由を表示） → ④ 一覧からモデルを選んで比較し、採用する1モデルだけをMAT保存。', 'all';
    'データの確認：学習画面の① で「グラフで傾向を見る」タブを開き、グラフの種類・横軸・縦軸・色（または列）を選んで「グラフを描く」を押します。表とグラフは結果の右下のボタンで保存・コピーできます。', 'all';
    'データの確認（Pro版）：グラフの種類で、ヒストグラム・相関マトリックス・分散分析（ANOVA）・Parallel Coordinates・Parallel Sets・Sankey Diagram・主成分分析（PCA）・クラスタリングも選べます。これらは「列」の一覧で対象の列を選びます（分散分析は縦軸が応答、「列」が要因）。', 'pro';
    '学習の変数：目的変数は複数選べ、列ごとに別のモデルを作ります（Ctrl キーを押しながら複数選択）。APCは4変数へ列を割り当て、Swing Curveは「下地なし／下地あり」と膜厚の列・下地の列を選び、汎用回帰は入力に使う列を選んで順序を確認します。', 'all';
    '条件の比較：③でカーネル（汎用回帰では回帰方式も）を複数選ぶと、まとめて学習して④で比べます。汎用回帰の回帰方式は GPR・重回帰・PLS・ランダムフォレスト・バギング木です。初期状態では交差検証を使わず学習データでの当てはまりで比べ、「交差検証で評価する」を選ぶと同じ分割の交差検証で比べます。以前の実行結果も④の一覧に残り、目的変数ごとに精度の順位で並びます。', 'standard';
    '条件の比較：③でカーネル（汎用回帰では回帰方式も）を複数選ぶと、まとめて学習して④で比べます。汎用回帰の回帰方式は GPR・重回帰・PLS・ランダムフォレスト・バギング木・EBM・XGBoost・LightGBM・CatBoost です。初期状態では交差検証を使わず学習データでの当てはまりで比べ、「交差検証で評価する」を選ぶと同じ分割の交差検証で比べます。以前の実行結果も④の一覧に残り、目的変数ごとに精度の順位で並びます。', 'pro';
    'ハイパーパラメータ（Pro版）：汎用回帰の③の下の「ハイパーパラメータ」で、編集する方式を選び、表の「値」を変えます。探索するときは「探索の方法」でグリッドサーチかランダムサーチを選び、「探索の候補」にカンマ区切りで値を入れます（空欄の項目は「値」に固定）。左下に試行数が表示されます。探索の結果は④で採用した行を選ぶと「探索の推移」「パラメータと精度」のグラフと「ハイパーパラメータ探索」の表で確認できます。', 'pro';
    '計算時間：条件ごとに分割数＋1回の学習を行います。ランダムフォレスト・バギング木は木の本数に比例して時間がかかります。SHAPは③のチェックで省略でき、④の「選択モデルのSHAPを計算」で後から計算できます。APCの交差検証は各分割の学習に25行以上が必要です。', 'standard';
    '計算時間：条件ごとに分割数＋1回の学習を行い、周期カーネルはその都度周期を探索します。ランダムフォレスト・バギング木・ブースティングは木の本数に比例して時間がかかり、ハイパーパラメータの探索は試行数×分割数の学習を行います。SHAPは③のチェックで省略でき、④の「選択モデルのSHAPを計算」で後から計算できます。APCの交差検証は各分割の学習に25行以上が必要です。', 'pro';
    '進捗と途中停止：モデリング・炉内補間・保存モデルでの推定・実験計画作成を実行すると、進捗バーに進んだ割合・経過時間・残り時間の目安を表示します。「キャンセル」で途中で止められます（今回の結果は表示・追加せず、以前の結果は残ります）。1回のモデルの学習や SHAP の計算は途中では止まらず、その計算が終わってから止まります。', 'standard';
    '進捗と途中停止：モデリング・炉内補間・保存モデルでの推定・実験計画作成・Sobol感度解析・因果探索・階層ベイズ・コピュラ乱数生成を実行すると、進捗バーに進んだ割合・経過時間・残り時間の目安を表示します。「キャンセル」で途中で止められます（今回の結果は表示・追加せず、以前の結果は残ります）。1回のモデルの学習（Sobol の代替モデルを含む）、SHAP の計算、コピュラの当てはめと生成は途中では止まらず、その計算が終わってから止まります。', 'pro';
    '周期カーネル（Pro版のみ）：Swing Curve学習の③で swingperiodic を選びます。探索範囲は同じ画面の「周期の探索範囲」で指定し、採用した周期と探索の履歴は④の「周期の最適化」とグラフで確認します。', 'pro';
    '炉内補間：① データ → ② WaferId・BoatSlot・バッチ・目的変数の列を確認 → ③ 方式と予測範囲を決めて実行 → ④ Run・目的変数・方式を切り替えて比較し、選んだ1モデルをMAT保存（専用の Furnace_Model 形式）。', 'all';
    '保存モデルで推定・SHAP：左の①でモデルを選びます。MATを開くほか、起動中に学習したモデルも保存せずに選べます。② データを開く → ③ 処理の種類と列を割り当て、「SHAPも計算する」を選ぶ → ④ 実行。実測列を選ぶと評価指標も計算し、SHAP の分布・依存図はどのモデルでも表示します。', 'all';
    'Sobol感度解析（Pro版）：① 対象を選ぶ（データなら Excel / CSV を開いて出力の列と入力の列、保存モデルならモデル）→ ② 下限・上限を確認・編集 → ③ 入力の分布・代替モデル・基本の標本数 N・平均 ± nσ の n を決める → ④ 実行。右に S1・ST の棒グラフと表、代替モデルの当てはまり、予測値の分布と統計を表示します。', 'pro';
    'コピュラ乱数生成（Pro版）：① 作り方を選ぶ（データなら Excel / CSV を開いて列を選ぶ、指定なら変数の数・分布・パラメータ・順位相関を入れる）→ ② コピュラの種類・周辺分布・個数・乱数seed → ③ 生成。「生成した乱数」の表を選んで「表を保存（CSV / Excel）」で保存します。', 'pro';
    '因果探索（Pro版）：① データを開く → ② 数値の列を2〜50列選ぶ → ③ PC アルゴリズムか DirectLiNGAM を選び、有意水準を決める → ④ 前もって分かっている因果を指定（任意）→ ⑤ 実行。右に因果グラフと辺の表（DirectLiNGAM では因果の順序も）を表示します。', 'pro';
    '階層ベイズ（Pro版）：① データを開く → ② 目的変数・グループの列・説明変数を選ぶ → ③ グループごとに推定する係数と MCMC の回数を決める → ④ 実行。右にグループごとの係数（全体の平均と、グループ単独の最小二乗と比べた図）、収束の確認、表を表示します。', 'pro';
    'Swing Curve近似（Pro版）：SHAP依存の RESIST_TH のグラフで膜厚・周期範囲を設定して更新します。「グラフを大きく表示」を押すと一覧をたたんで広く表示できます。三角関数は異なる膜厚8点以上、スプライン補間は4点以上が必要です。', 'pro';
    '残差診断（Pro版）：近似カーブ横の「残差分布」「正規Q–Q」「残差対膜厚」で確認。「残差の正規性」「残差データ」の表はCSV/Excelへ保存。ばらつきが数値しきい値以下なら検定・形状統計を対象外と表示します。', 'pro';
    '書出し：結果の右下の「表を保存」で表示中の表を CSV / Excel へ、「グラフをPNG保存」で図を保存します。「グラフをコピー」で画像をクリップボードへ入れ、ExcelやPowerPointへ貼り付けられます。', 'all';
    '実験計画：D最適・I最適・直交表から選びます。1〜8因子、水準数2〜5、実験数1〜300件。直交表は実験数を自動で決めます。D最適・I最適は局所探索のため最良の保証はありません。I最適の積分対象は連続な一様領域 [-1,1]^k です。作成すると「計画の評価指標」の表（D効率・A効率・I基準・G効率・最大VIFなど）と予測分散の分布を表示します。', 'standard';
    '実験計画：D最適・I最適・直交表に加え、既存の計画に点を追加する拡張 D最適・拡張 I最適（Pro版のみ）を選べます。1〜8因子、水準数2〜5、追加1〜300件、既存＋追加500件以下。直交表は実験数を自動で決めます。D最適・I最適は局所探索のため最良の保証はありません。I最適の積分対象は連続な一様領域 [-1,1]^k です。作成すると「計画の評価指標」の表（D効率・A効率・I基準・G効率・最大VIFなど）と予測分散の分布を表示します。拡張計画では既存＋追加の全体で評価します。', 'pro';
    'ワードクラウド（Pro版）：文章を入力するかテキストファイルを開き、「見た目（形と色）」で形・配色・色・表示する単語の数を選んで「ワードクラウドを作成」を押します。', 'pro';
    [settings_title '：保存先、テーマ、文字の大きさ、カーネルの初期値、Fit method、KL / MIビン数、実験計画の因子数・実験数・seed、炉内補間のRBF幅・正則化を変更できます。文字の大きさは保存するとすぐ反映し、それ以外は次の実行から反映します。表示中の結果や学習済みモデルの一覧は消えません。'], 'all';
    '下の状況欄：各画面の下に、処理の状況と注意を新しい順に表示します。エラーや注意はダイアログでも表示します。', 'all'};
operations = for_edition(operations, is_pro);
uitextarea(layout, 'Editable', 'off', 'Value', operations);
% {関数名, ヘルプのフォルダ, 対象の版}
functions = {
    'fitrgp', 'stats', 'all'; 'RegressionGP', 'stats', 'all'; 'RegressionGP.predict', 'stats', 'all';
    'fitrensemble', 'stats', 'all'; 'templateTree', 'stats', 'all'; 'plsregress', 'stats', 'all';
    'shapley', 'stats', 'all'; 'shapley.swarmchart', 'stats', 'all'; 'swarmchart', 'matlab/ref', 'all';
    'cvpartition', 'stats', 'all'; 'crossval', 'stats', 'all'; 'rng', 'matlab/ref', 'all'; 'randperm', 'matlab/ref', 'all';
    'spline', 'matlab/ref', 'all'; 'ppval', 'matlab/ref', 'all'; 'polyfit', 'matlab/ref', 'all'; 'polyval', 'matlab/ref', 'all';
    'fill', 'matlab/ref', 'all'; 'cordexch', 'stats', 'all'; 'fracfact', 'stats', 'all'; 'daugment', 'stats', 'pro';
    'lillietest', 'stats', 'pro'; 'skewness', 'stats', 'pro'; 'kurtosis', 'stats', 'pro'; 'norminv', 'stats', 'pro';
    'histogram', 'matlab/ref', 'pro'; 'corr', 'stats', 'pro'; 'anovan', 'stats', 'pro'; 'boxchart', 'matlab/ref', 'pro';
    'pca', 'stats', 'pro'; 'kmeans', 'stats', 'pro'; 'linkage', 'stats', 'pro';
    'silhouette', 'stats', 'pro'; 'dendrogram', 'stats', 'pro'; 'wordcloud', 'matlab/ref', 'pro'; 'copygraphics', 'matlab/ref', 'all';
    'sobolset', 'stats', 'pro'; 'digraph', 'matlab/ref', 'pro'; 'iwishrnd', 'stats', 'pro'; 'gamrnd', 'stats', 'pro';
    'copulafit', 'stats', 'pro'; 'copularnd', 'stats', 'pro'; 'copulaparam', 'stats', 'pro'; 'fitdist', 'stats', 'pro'; 'ksdensity', 'stats', 'pro'};
functions = functions(ismember(functions(:, 3), [{'all'}, {edition}]), :);
LINK_ROW_HEIGHT = 30;
links = uigridlayout(layout, [ceil(size(functions, 1) / 4), 4]); links.Padding = [0, 0, 0, 0];
layout.RowHeight{5} = ceil(size(functions, 1) / 4) * LINK_ROW_HEIGHT;
for index = 1:size(functions, 1)
    url = ['https://www.mathworks.com/help/' functions{index, 2} '/' lower(functions{index, 1}) '.html'];
    uibutton(links, 'Text', [functions{index, 1} ' ↗'], 'ButtonPushedFcn', @(~, ~) web(url, '-browser'));
end

guide_paths = cellstr(guide_paths);
if ~is_pro, layout.RowHeight{end} = 0; return; end
buttons = uigridlayout(layout, [1, 2]); buttons.Padding = [0, 0, 0, 0];
uibutton(buttons, 'Text', '利用者向け手順書を開く（画面の使い方）', 'FontWeight', 'bold', ...
    'ButtonPushedFcn', @(~, ~) web(guide_paths{1}, '-browser'));
if numel(guide_paths) > 1
    uibutton(buttons, 'Text', 'ビルド・利用手順書を開く（作成・配布担当者向け）', ...
        'ButtonPushedFcn', @(~, ~) web(guide_paths{2}, '-browser'));
end
end

function rows = for_edition(rows, is_pro)
% 最後の列（対象の版）で絞り込み、表示する列だけを返す。
edition = 'standard'; if is_pro, edition = 'pro'; end
keep = ismember(rows(:, end), {'all', edition});
rows = rows(keep, 1:end - 1);
end

function showTerm(event, terms, description)
if isempty(event.Indices), return; end
row = event.Indices(1, 1); description.Value = {terms{row, 1}; terms{row, 2}};
end
